<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Slide in Animation</title>
    <style>
        .fade {
            position: fixed;
            width: 100%;
            height: 100%;
            top: 0;
            left: 0;
            background-color: rgba(0, 0, 0, 0.5);
            z-index: 1000;
            opacity: 0;
        }
        .fade.fade-in {
            opacity: 1;
        }
    </style>
</head>
<body>
    <div id="animation" class="fade"></div>

    <script>
        // Slide in animation
        const animationDiv = document.getElementById('animation');

        // Animate the div to slide in from the right
        animationDiv.style.opacity = '0';
        animationDiv.style.left = '50%';

        setTimeout(() => {
            animationDiv.style.opacity = '1';
        }, 2000); // Slide in for 2 seconds

        // Fade out animation after 2 seconds
        setTimeout(() => {
            animationDiv.style.left = '0';
            animationDiv.style.opacity = '0';
        }, 4000); // Fade out for 4 seconds
    </script>
</body>
</html>
```

