```cpp
#include <bits/stdc++.h>
#define int long long

using namespace std;

signed main() {
    freopen("mixmilk.in", "r", stdin);
    freopen("mixmilk.out", "w", stdout);

    int n = 3, turns = 100;
    cin >> n;

    vector<int> capacity(n);
    vector<int> milk(n);

    for (int i = 0; i < n; i++) {
        cin >> capacity[i]; cin >> milk[i];
    }

    for (int i = 0; i < turns; i++) {
        int bucket1 = i % n;
        int bucket2 = (i + 1) % n;

        int amt = min(milk[bucket1], capacity[bucket2] - milk[bucket2]);

        milk[bucket1] -= amt;
        milk[bucket2] += amt;
    }

    for (int m : milk) {
        cout << m << endl;
    }

    return 0;
}
```
